use vstd::prelude::*;

verus! {

/// Returns a vector of length `n` in which every entry is `1`.
fn ones(n: usize) -> (result: Vec<i8>)
    ensures
        // the length is exactly n
        result.len() == n,
        // every element at index i is 1
        forall |i: usize| i < n ==> result[i] == 1,
        // any two elements in range are equal
        forall |i: usize, j: usize| i < n && j < n ==> result[i] == result[j],
        // every element is strictly positive
        forall |i: usize| i < n ==> result[i] > 0
{
    let mut vec: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            vec.len() == i,
            forall |j: usize| j < i ==> vec[j] == 1,
        decreases n - i,
    {
        vec.push(1);
        i = i + 1;
    }
    vec
}

}

